style.css:
@-moz-document url("https://www.pinterest.com/") {
/* Фон всей страницы - ваше изображение */
  body {
    background-image: url("https://your-image-url-here");
    background-size: cover;
    background-position: center;
    background-repeat: no-repeat;
  }

  /* Сделаем затемнение для лучшей читаемости */
  #__PWS_ROOT, div[data-test-id="searchResults"] {
    background-color: rgba(0, 0, 0, 0.4) !important;
  }

  /* Настройка элементов интерфейса для контраста */
  * {
    color: #fff !important;
  }

  /* Изначальные карточки пинов */
  div[data-test-id="pin"] {
    background-color: rgba(255, 255, 255, 0.1) !important;
    border-radius: 10px;
  }

  /* Улыбаясь, делая интерфейс более стильным */
  header, footer {
    background-color: transparent !important;
  }
}
